#' Spatial DID (Spillovers)
#'
#' 
#' @param data .
#' @param dep .
#' @param treat .
#' @param covs .
#' @param timeVar .
#' @param idVar .
#' @param xVar .
#' @param yVar .
#' @param wSource .
#' @param wFile .
#' @param wIdField .
#' @param wMethod .
#' @param wK .
#' @param wDist .
#' @param wPower .
#' @param wCutoff .
#' @param wOrder .
#' @param wCumul .
#' @param wSymm .
#' @param wLonLat .
#' @param wStyle .
#' @param showGuide .
#' @param showHelp .
#' @param rings .
#' @param lagTreat .
#' @param effects .
#' @param se .
#' @param conleyBw .
#' @param conleyLag .
#' @param level .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$guide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$helpText} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$notes} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$coef} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$fit} \tab \tab \tab \tab \tab a table \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$coef$asDF}
#'
#' \code{as.data.frame(results$coef)}
#'
#' @export
spdid <- function(
    data,
    dep,
    treat,
    covs,
    timeVar,
    idVar,
    xVar,
    yVar,
    wSource = "coords",
    wFile = "",
    wIdField = "",
    wMethod = "auto",
    wK = 5,
    wDist = 0,
    wPower = 1,
    wCutoff = 0,
    wOrder = 1,
    wCumul = FALSE,
    wSymm = FALSE,
    wLonLat = FALSE,
    wStyle = "W",
    showGuide = FALSE,
    showHelp = FALSE,
    rings = "",
    lagTreat = FALSE,
    effects = "twoway",
    se = "cluster",
    conleyBw = 0,
    conleyLag = 0,
    level = 95) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("spdid requires jmvcore to be installed (restart may be required)")

    if ( ! missing(dep)) dep <- jmvcore::resolveQuo(jmvcore::enquo(dep))
    if ( ! missing(treat)) treat <- jmvcore::resolveQuo(jmvcore::enquo(treat))
    if ( ! missing(covs)) covs <- jmvcore::resolveQuo(jmvcore::enquo(covs))
    if ( ! missing(timeVar)) timeVar <- jmvcore::resolveQuo(jmvcore::enquo(timeVar))
    if ( ! missing(idVar)) idVar <- jmvcore::resolveQuo(jmvcore::enquo(idVar))
    if ( ! missing(xVar)) xVar <- jmvcore::resolveQuo(jmvcore::enquo(xVar))
    if ( ! missing(yVar)) yVar <- jmvcore::resolveQuo(jmvcore::enquo(yVar))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(dep), dep, NULL),
            `if`( ! missing(treat), treat, NULL),
            `if`( ! missing(covs), covs, NULL),
            `if`( ! missing(timeVar), timeVar, NULL),
            `if`( ! missing(idVar), idVar, NULL),
            `if`( ! missing(xVar), xVar, NULL),
            `if`( ! missing(yVar), yVar, NULL))


    options <- spdidOptions$new(
        dep = dep,
        treat = treat,
        covs = covs,
        timeVar = timeVar,
        idVar = idVar,
        xVar = xVar,
        yVar = yVar,
        wSource = wSource,
        wFile = wFile,
        wIdField = wIdField,
        wMethod = wMethod,
        wK = wK,
        wDist = wDist,
        wPower = wPower,
        wCutoff = wCutoff,
        wOrder = wOrder,
        wCumul = wCumul,
        wSymm = wSymm,
        wLonLat = wLonLat,
        wStyle = wStyle,
        showGuide = showGuide,
        showHelp = showHelp,
        rings = rings,
        lagTreat = lagTreat,
        effects = effects,
        se = se,
        conleyBw = conleyBw,
        conleyLag = conleyLag,
        level = level)

    analysis <- spdidClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

